import fs from 'node:fs';
import assert from 'node:assert/strict';
import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-orbital-ct-website',site=stage+'/website';
const prep=json(stage+'/PREPARATION.json'),old=json(stage+'/preimages/tests/fixtures/current-atlas-delivery.json.raw');
assert.equal(hash(prep.atlasReceipt),prep.atlasReceiptSha256);
assert.equal(hash(prep.parentReceipt),prep.parentReceiptSha256);
const manifest=json(site+'/atlas-review/manifest.json'),binding=json(site+'/atlas-review/integration-inputs.json'),viewer=json(site+'/public/atlas-review-viewer/manifest.json');
assert.equal(manifest.revision,prep.atlasHead);assert.equal(binding.sourceCommit,prep.atlasHead);
assert.equal(viewer.sourceCommit,prep.atlasHead);assert.equal(viewer.websiteIntegrationSha256,binding.sha256);
assert.equal(viewer.personalRecordsIncluded,false);assert.equal(viewer.mode,'production');
for(const r of binding.inputs)assert.equal(hash(site+'/'+r.path),r.sha256,r.path);
for(const r of manifest.files)assert.equal(hash(site+'/atlas-review/'+r.path),r.importedSha256,r.path);
for(const r of viewer.files)assert.equal(hash(site+'/public/atlas-review-viewer/'+r.path),r.sha256,r.path);
const runtimeSources=Object.fromEntries(Object.keys(old.runtimeSources).map(n=>[n,json(site+'/public/atlas-runtime/'+n+'/manifest.json').sourceCommit]));
for(const revision of Object.values(runtimeSources))assert.equal(revision,prep.atlasHead);
const pin={...old,source:prep.atlasHead,sourceTree:prep.atlasTree,runtimeSources,reviewSourceFiles:manifest.files.length,reviewIntegration:binding.sha256,viewerFiles:viewer.files.length,viewerPackages:viewer.packages.length,documents:Object.fromEntries(Object.keys(old.documents).map(p=>[p,hash(site+'/'+p)]))};
fs.writeFileSync(site+'/tests/fixtures/current-atlas-delivery.json',JSON.stringify(pin,null,2)+'\n');
const receipt={at:new Date().toISOString(),pin,pinSha256:hash(site+'/tests/fixtures/current-atlas-delivery.json'),sourceFiles:manifest.files.length,inputs:binding.inputs.length,viewerFiles:viewer.files.length,viewerPackages:viewer.packages.length,binding:binding.sha256,previewChanged:false};
fs.writeFileSync(stage+'/CAPTURE.json',JSON.stringify(receipt,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({source:pin.source,sourceFiles:receipt.sourceFiles,inputs:receipt.inputs,binding:receipt.binding,captureSha256:hash(stage+'/CAPTURE.json')}));
